-- Round 3: the songbook (SPEC §9.6, §11; songbook design, task 3.1).
--
-- Generated by `prisma migrate dev --create-only`, then edited by hand in
-- exactly one place (keep it that way, or the next `migrate dev` proposes a
-- reset, F-009): the CHECK constraints are appended at the end.
-- Prisma sends the script as one implicit transaction, so any failure rolls
-- everything back.

-- CreateTable
CREATE TABLE "songs" (
    "id" TEXT NOT NULL,
    "club_id" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "title_key" TEXT NOT NULL,
    "artist" TEXT,
    "melody" TEXT,
    "body" TEXT NOT NULL,
    "source_key" TEXT,
    "import_hash" TEXT,
    "created_by_id" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "songs_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "songs_club_id_title_key_key" ON "songs"("club_id", "title_key");

-- CreateIndex
CREATE UNIQUE INDEX "songs_club_id_source_key_key" ON "songs"("club_id", "source_key");

-- AddForeignKey
ALTER TABLE "songs" ADD CONSTRAINT "songs_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "clubs"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "songs" ADD CONSTRAINT "songs_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ─── Hand edit: CHECK constraints (SPEC §11) ────────────────────────────────
-- Prisma cannot express CHECKs and ignores them when diffing (F-004: CHECKs
-- only, never raw indexes or FKs). The app cleans and validates first
-- (src/lib/validation/song.ts, src/server/domain/songs/*), and so does the
-- importer (scripts/import-songbook.ts); these guard every writer.

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_title_length_check"
  CHECK (char_length(btrim("title")) BETWEEN 1 AND 120);

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_title_key_not_empty_check"
  CHECK ("title_key" <> '');

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_artist_length_check"
  CHECK ("artist" IS NULL OR char_length(btrim("artist")) BETWEEN 1 AND 120);

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_melody_length_check"
  CHECK ("melody" IS NULL OR char_length(btrim("melody")) BETWEEN 1 AND 120);

-- The body keeps leading spaces (chord columns), so only its length and "not
-- only blank lines" are checked here.
ALTER TABLE "songs"
  ADD CONSTRAINT "songs_body_length_check"
  CHECK (char_length("body") <= 20000 AND btrim("body", E' \n') <> '');

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_source_key_length_check"
  CHECK ("source_key" IS NULL OR char_length("source_key") BETWEEN 1 AND 300);

ALTER TABLE "songs"
  ADD CONSTRAINT "songs_import_hash_format_check"
  CHECK ("import_hash" IS NULL OR "import_hash" ~ '^[0-9a-f]{64}$');

-- Provenance comes in pairs: an imported song has both, an app-made one neither.
ALTER TABLE "songs"
  ADD CONSTRAINT "songs_import_pair_check"
  CHECK (("source_key" IS NULL) = ("import_hash" IS NULL));
